import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const n = Number(input[0]);

const small: number[] = [];
const large: number[] = [];
for (let d = 1; d * d <= n; d++) {
  if (n % d !== 0) continue;
  small.push(d);
  // 対になる約数（平方数のときは同じ値を 2 回入れない）
  if (d !== n / d) large.push(n / d);
}
console.log([...small, ...large.reverse()].join(" "));
